//! RFC 9383's test vectors (Appendix C) for the suites this crate
//! implements, as the RFC prints them: hex, with the context and the
//! identities the vectors are run with.

/// One test vector. The PBKDF is left out: `w0` and `w1` are given.
pub(crate) struct Vector {
    pub(crate) context: &'static [u8],
    pub(crate) prover_id: &'static [u8],
    pub(crate) verifier_id: &'static [u8],
    /// `w0`.
    pub(crate) w0: &'static str,
    /// `w1`.
    pub(crate) w1: &'static str,
    /// `L = w1*P`.
    pub(crate) l: &'static str,
    /// The prover's `x`.
    pub(crate) x: &'static str,
    /// `shareP = X`.
    pub(crate) share_p: &'static str,
    /// The verifier's `y`.
    pub(crate) y: &'static str,
    /// `shareV = Y`.
    pub(crate) share_v: &'static str,
    /// `Z`.
    pub(crate) z: &'static str,
    /// `V`.
    pub(crate) v: &'static str,
    /// The transcript `TT`.
    pub(crate) tt: &'static str,
    /// `K_main = Hash(TT)`.
    pub(crate) k_main: &'static str,
    /// `K_confirmP`.
    pub(crate) k_confirm_p: &'static str,
    /// `K_confirmV`.
    pub(crate) k_confirm_v: &'static str,
    /// `confirmP = MAC(K_confirmP, shareV)`.
    pub(crate) confirm_p: &'static str,
    /// `confirmV = MAC(K_confirmV, shareP)`.
    pub(crate) confirm_v: &'static str,
    /// `K_shared`.
    pub(crate) k_shared: &'static str,
}

